1	/*
2	 ########################################################################
3	 Epiphany eLink AXI Master Module
4	 ######################################################################## 
5	
6	  NOTES:
7	 --write channels: write address, write data, write response
8	 --read channels: read address, read data channel
9	 --'valid' source signal used to show valid address,data,control is available
10	 --'ready' destination  ready signal indicates readyness to accept information
11	 --'last' signal indicates the transfer of final data item
12	 --read and write have separate address channels
13	 --read data channel carries read data from slave to master
14	 --write channel includes a byte lane strobe signal for every eight data bits
15	 --there is no acknowledge on write, treated as buffered 
16	 --channels are unidirectional
17	 --valid is asserted uncondotionally
18	 --ready occurs cycle after valid
19	 --there can be no combinatorial path between input and output of interface
20	 --destination is permitted to wait for valud before asserting READY
21	 --source is not allowed to wait for READY to assert VALID
22	 --AWVALID must remain asserted until the rising clock edge after slave asserts AWREADY??
23	 --The default state of AWREADY can be either HIGH or LOW. This specification recommends a default state of HIGH.
24	 --During a write burst, the master can assert the WVALID signal only when it drives valid write data.
25	 --The default state of WREADY can be HIGH, but only if the slave can always accept write data in a single cycle.
26	 --The master must assert the WLAST signal while it is driving the final write transfer in the burst.
27	
28	 --_aw=write address channel
29	 --_ar=read address channel
30	 --_r=read data channel
31	 --_w=write data channel
32	 --_b=write response channel
33	
34	  */
35	
36	module emaxi(/*autoarg*/
37	   // Outputs
38	   wr_wait, rd_wait, rr_access, rr_packet, m_axi_awid, m_axi_awaddr,
39	   m_axi_awlen, m_axi_awsize, m_axi_awburst, m_axi_awlock,
40	   m_axi_awcache, m_axi_awprot, m_axi_awqos, m_axi_awvalid, m_axi_wid,
41	   m_axi_wdata, m_axi_wstrb, m_axi_wlast, m_axi_wvalid, m_axi_bready,
42	   m_axi_arid, m_axi_araddr, m_axi_arlen, m_axi_arsize, m_axi_arburst,
43	   m_axi_arlock, m_axi_arcache, m_axi_arprot, m_axi_arqos,
44	   m_axi_arvalid, m_axi_rready,
45	   // Inputs
46	   wr_access, wr_packet, rd_access, rd_packet, rr_wait, m_axi_aclk,
47	   m_axi_aresetn, m_axi_awready, m_axi_wready, m_axi_bid, m_axi_bresp,
48	   m_axi_bvalid, m_axi_arready, m_axi_rid, m_axi_rdata, m_axi_rresp,
49	   m_axi_rlast, m_axi_rvalid
50	   );
51	
52	   parameter M_IDW  = 12;
53	   parameter PW     = 104;
54	   parameter AW     = 32;
55	   parameter DW     = 32;
56	
57	   //########################
58	   //EMESH INTERFACE
59	   //########################
60	
61	   //Write request
62	   input 	       wr_access;
63	   input [PW-1:0]      wr_packet;   
64	   output 	       wr_wait;
65	   
66	   //Read request
67	   input 	       rd_access;
68	   input [PW-1:0]      rd_packet;
69	   output 	       rd_wait;
70	   
71	   //Read response
72	   output 	       rr_access;
73	   output [PW-1:0]     rr_packet;
74	   input 	       rr_wait;
75	
76	   //########################
77	   //AXI MASTER INTERFACE
78	   //########################
79	
80	   input  	       m_axi_aclk;    // global clock signal.
81	   input  	       m_axi_aresetn; // global reset singal.
82	
83	   //Write address channel
84	   output [M_IDW-1:0]  m_axi_awid;    // write address ID
85	   output [31 : 0]     m_axi_awaddr;  // master interface write address   
86	   output [7 : 0]      m_axi_awlen;   // burst length.
87	   output [2 : 0]      m_axi_awsize;  // burst size.
88	   output [1 : 0]      m_axi_awburst; // burst type.
89	   output              m_axi_awlock;  // lock type   
90	   output [3 : 0]      m_axi_awcache; // memory type.
91	   output [2 : 0]      m_axi_awprot;  // protection type.
92	   output [3 : 0]      m_axi_awqos;   // quality of service
93	   output 	       m_axi_awvalid; // write address valid
94	   input 	       m_axi_awready; // write address ready
95	
96	   //Write data channel
97	   output [M_IDW-1:0]  m_axi_wid;     
98	   output [63 : 0]     m_axi_wdata;   // master interface write data.
99	   output [7 : 0]      m_axi_wstrb;   // byte write strobes
100	   output 	       m_axi_wlast;   // last transfer in a write burst.
101	   output 	       m_axi_wvalid;  // indicates data is ready to go
102	   input 	       m_axi_wready;  // slave is ready for data
103	
104	   //Write response channel
105	   input [M_IDW-1:0]   m_axi_bid;
106	   input [1 : 0]       m_axi_bresp;   // status of the write transaction.
107	   input 	       m_axi_bvalid;  // channel is a valid write response
108	   output 	       m_axi_bready;  // master can accept write response.
109	
110	   //Read address channel
111	   output [M_IDW-1:0]  m_axi_arid;    // read address ID
112	   output [31 : 0]     m_axi_araddr;  // initial address of a read burst
113	   output [7 : 0]      m_axi_arlen;   // burst length
114	   output [2 : 0]      m_axi_arsize;  // burst size
115	   output [1 : 0]      m_axi_arburst; // burst type
116	   output              m_axi_arlock;  // lock type   
117	   output [3 : 0]      m_axi_arcache; // memory type
118	   output [2 : 0]      m_axi_arprot;  // protection type
119	   output [3 : 0]      m_axi_arqos;   // quality of service info
120	   output 	       m_axi_arvalid; // valid read address
121	   input 	       m_axi_arready; // slave is ready to accept an address
122	
123	   //Read data channel   
124	   input [M_IDW-1:0]   m_axi_rid;     // read data ID
125	   input [63 : 0]      m_axi_rdata;   // master read data
126	   input [1 : 0]       m_axi_rresp;   // status of the read transfer
127	   input 	       m_axi_rlast;   // last transfer in a read burst
128	   input 	       m_axi_rvalid;  // signaling the required read data
129	   output 	       m_axi_rready;  // master can accept the readback data
130	  
131	
132	   //#########################################################################
133	   //REGISTER/WIRE DECLARATIONS
134	   //#########################################################################
135	   reg [31 : 0]        m_axi_awaddr;
136	   reg [7:0] 	       m_axi_awlen;
137	   reg [2:0] 	       m_axi_awsize;
138	   reg 		       m_axi_awvalid;
139	   reg [63 : 0]        m_axi_wdata;
140	   reg [63 : 0]        m_axi_rdata_reg;
141	   reg [7 : 0] 	       m_axi_wstrb;
142	   reg 		       m_axi_wlast;
143	   reg 		       m_axi_wvalid;
144	   reg 		       awvalid_b;
145	   reg [31:0] 	       awaddr_b;
146	   reg [2:0] 	       awsize_b;
147	   reg [7:0] 	       awlen_b;
148	   reg 		       wvalid_b;
149	   reg [63:0] 	       wdata_b;
150	   reg [7:0] 	       wstrb_b;
151	   reg [63 : 0]        wdata_aligned;
152	   reg [7 : 0] 	       wstrb_aligned;
153	   
154	   reg 		       rr_access;
155	   reg [31:0] 	       rr_data;
156	   reg [31:0] 	       rr_srcaddr;
157	   reg [3:0] 	       rr_datamode;
158	   reg [3:0] 	       rr_ctrlmode;
159	   reg [31:0] 	       rr_dstaddr;
160	   reg [63:0] 	       m_axi_rdata_fifo;
161	   reg 		       rr_access_fifo;
162	  
163	   
164	   //wires
165	   wire 	       aw_go;
166	   wire 	       w_go;
167	   wire 	       readinfo_wren;
168	   wire 	       readinfo_full;
169	   wire [40:0] 	       readinfo_out;
170	   wire [40:0] 	       readinfo_in;
171	   wire 	       awvalid_in;
172	   
173	   wire [1:0] 	       wr_datamode;
174	   wire [AW-1:0]       wr_dstaddr;
175	   wire [DW-1:0]       wr_data;
176	   wire [AW-1:0]       wr_srcaddr;
177	
178	   wire [1:0] 	       rd_datamode;
179	   wire [4:0] 	       rd_ctrlmode;
180	   wire [AW-1:0]       rd_dstaddr;
181	   wire [AW-1:0]       rd_srcaddr;
182	
183	   wire [1:0] 	       rr_datamode_fifo;
184	   wire [3:0] 	       rr_ctrlmode_fifo;
185	   wire [31:0] 	       rr_dstaddr_fifo;
186	   wire [2:0] 	       rr_alignaddr_fifo;
187	   wire [103:0]        packet_out;   
188	   wire 	       fifo_prog_full;
189	   wire 	       fifo_full;   	
190	   wire 	       fifo_rd_en;
191	   wire 	       fifo_wr_en;
192	   
193	   //#########################################################################
194	   //EMESH 2 PACKET CONVERSION
195	   //#########################################################################
196	
197	   //RXWR
198	   packet2emesh p2e_rxwr (
199				  // Outputs
200				  .write_in		(),
201				  .datamode_in		(wr_datamode[1:0]),
202				  .ctrlmode_in		(),
203				  .dstaddr_in		(wr_dstaddr[AW-1:0]),
204				  .data_in		(wr_data[DW-1:0]),
205				  .srcaddr_in		(wr_srcaddr[AW-1:0]),
206				  // Inputs
207				  .packet_in		(wr_packet[PW-1:0])
208				  );
209	   
210	   //RXRD
211	   packet2emesh p2e_rxrd (
212				  // Outputs
213				  .write_in		(),
214				  .datamode_in		(rd_datamode[1:0]),
215				  .ctrlmode_in		(rd_ctrlmode[4:0]),
216				  .dstaddr_in		(rd_dstaddr[AW-1:0]),
217				  .data_in		(),
218				  .srcaddr_in		(rd_srcaddr[AW-1:0]),
219				  // Inputs
220				  .packet_in		(rd_packet[PW-1:0])
221				  );
222	
223	   //RR
224	   emesh2packet e2p (
225			     // Outputs
226			     .packet_out	(rr_packet[PW-1:0]),
227			     // Inputs
228			     .write_out		(1'b1),
229			     .datamode_out	(rr_datamode[1:0]),
230			     .ctrlmode_out	({1'b0,rr_ctrlmode[3:0]}),
231			     .dstaddr_out	(rr_dstaddr[AW-1:0]),
232			     .data_out		(rr_data[DW-1:0]),
233			     .srcaddr_out	(rr_srcaddr[AW-1:0])
234			     );
235	   			    
236	   //#########################################################################
237	   //AXI unimplemented constants
238	   //#########################################################################
239	
240	   //AW
241	   assign m_axi_awid[M_IDW-1:0]  = {(M_IDW){1'b0}};
242	   assign m_axi_awburst[1:0]	= 2'b01; //only increment burst supported
243	   assign m_axi_awcache[3:0]	= 4'b0000; //TODO: should this be 0000 or 0010???
244	   assign m_axi_awprot[2:0]	= 3'b000;
245	   assign m_axi_awqos[3:0]	= 4'b0000;
246	   assign m_axi_awlock          = 1'b0;
247	
248	   //AR
249	   assign m_axi_arid[M_IDW-1:0] = {(M_IDW){1'b0}};
250	   assign m_axi_arburst[1:0]	= 2'b01; //only increment burst supported
251	   assign m_axi_arcache[3:0]	= 4'b0000;
252	   assign m_axi_arprot[2:0]	= 3'h0;
253	   assign m_axi_arqos[3:0]	= 4'h0;
254	   assign m_axi_arlock          = 1'b0;
255	    
256	   //B
257	   assign m_axi_bready    	= 1'b1;//TODO: tie to wait signal????   
258	
259	   //W
260	   assign m_axi_wid[M_IDW-1:0]  = {(M_IDW){1'b0}};
261	
262	   //#########################################################################
263	   //Write address channel
264	   //#########################################################################
265	
266	   assign aw_go       = m_axi_awvalid & m_axi_awready;
267	   assign w_go        = m_axi_wvalid  & m_axi_wready;
268	   assign wr_wait     = awvalid_b | wvalid_b;
269	   assign awvalid_in  = wr_access & ~awvalid_b & ~wvalid_b;
270	   
271	   // generate write-address signals
272	   always @( posedge m_axi_aclk )     
273	     if(!m_axi_aresetn) 
274	       begin
275	          m_axi_awvalid      <= 1'b0;
276	          m_axi_awaddr[31:0] <= 32'd0;
277	          m_axi_awlen[7:0]   <= 8'd0;
278	          m_axi_awsize[2:0]  <= 3'd0;	  
279	          awvalid_b          <= 1'b0;
280	          awaddr_b           <= 'd0;
281	          awlen_b[7:0]       <= 'd0;
282	          awsize_b[2:0]      <= 'd0;
283	       end 
284	     else 
285	       begin
286	          if( ~m_axi_awvalid | aw_go ) 
287		    begin
288	               if( awvalid_b ) 
289			 begin
290			    m_axi_awvalid       <= 1'b1;
291			    m_axi_awaddr[31:0]  <= awaddr_b[31:0];
292			    m_axi_awlen[7:0]    <= awlen_b[7:0];
293			    m_axi_awsize[2:0]   <= awsize_b[2:0];
294			 end 
295		      else 
296			begin
297			   m_axi_awvalid       <= awvalid_in;
298			   m_axi_awaddr[31:0]  <= wr_dstaddr[31:0];
299			   m_axi_awlen[7:0]    <= 8'b0;
300			   m_axi_awsize[2:0]   <= { 1'b0, wr_datamode[1:0]};
301			end
302		    end
303	          if( awvalid_in & m_axi_awvalid & ~aw_go )
304	            awvalid_b <= 1'b1;
305	          else if( aw_go )
306	            awvalid_b <= 1'b0;
307	          
308		 //Pipeline stage
309	         if( awvalid_in )
310		   begin
311	              awaddr_b[31:0]  <= wr_dstaddr[31:0];
312	              awlen_b[7:0]    <= 8'b0;
313	              awsize_b[2:0]   <= { 1'b0, wr_datamode[1:0] };
314	         end        
315	       end // else: !if(~m_axi_aresetn)
316	   
317	   //#########################################################################
318	   //Write data alignment circuit
319	   //#########################################################################
320	
321	   always @*
322	     case( wr_datamode[1:0] )        
323	       2'b00:    wdata_aligned[63:0] = { 8{wr_data[7:0]}};
324	       2'b01:    wdata_aligned[63:0] = { 4{wr_data[15:0]}};
325	       2'b10:    wdata_aligned[63:0] = { 2{wr_data[31:0]}};
326	       default: wdata_aligned[63:0]  = { wr_srcaddr[31:0], wr_data[31:0]};
327	     endcase
328	
329	   always @*
330	     begin
331		case(wr_datamode[1:0])
332	          2'd0: // byte
333	            case(wr_dstaddr[2:0])
334	              3'd0:    wstrb_aligned[7:0] = 8'h01;
335	              3'd1:    wstrb_aligned[7:0] = 8'h02;
336	              3'd2:    wstrb_aligned[7:0] = 8'h04;
337	              3'd3:    wstrb_aligned[7:0] = 8'h08;
338	              3'd4:    wstrb_aligned[7:0] = 8'h10;
339	              3'd5:    wstrb_aligned[7:0] = 8'h20;
340	              3'd6:    wstrb_aligned[7:0] = 8'h40;
341	              default: wstrb_aligned[7:0] = 8'h80;
342	            endcase
343	          2'd1: // 16b hword
344	            case(wr_dstaddr[2:1])
345	              2'd0:    wstrb_aligned[7:0] = 8'h03;
346	              2'd1:    wstrb_aligned[7:0] = 8'h0c;
347	              2'd2:    wstrb_aligned[7:0] = 8'h30;
348	              default: wstrb_aligned[7:0] = 8'hc0;
349	            endcase
350	          2'd2: // 32b word
351	            if(wr_dstaddr[2])
352		      wstrb_aligned[7:0] = 8'hf0;
353	            else
354		      wstrb_aligned[7:0] = 8'h0f;
355		  2'd3: 
356		    wstrb_aligned[7:0] = 8'hff;
357		endcase // case (emwr_datamode[1:0])
358	     end // always @ *
359	
360	   //#########################################################################
361	   //Write data channel
362	   //#########################################################################
363	
364	   always @ (posedge m_axi_aclk )
365	     if(~m_axi_aresetn) 
366	       begin	  
367		  m_axi_wvalid      <= 1'b0;
368	          m_axi_wdata[63:0] <= 64'b0;
369	          m_axi_wstrb[7:0]  <= 8'b0;
370	          m_axi_wlast       <= 1'b1; // TODO:bursts!!	  
371	          wvalid_b          <= 1'b0;
372	          wdata_b[63:0]     <= 64'b0;
373	          wstrb_b[7:0]      <= 8'b0;         
374	       end 
375	     else 
376	       begin
377	          if( ~m_axi_wvalid | w_go ) 
378		    begin
379	            if( wvalid_b ) 
380		      begin
381			 m_axi_wvalid       <= 1'b1;
382			 m_axi_wdata[63:0]  <= wdata_b[63:0];
383			 m_axi_wstrb[7:0]   <= wstrb_b[7:0];
384	              end 
385		    else 
386		      begin
387			 m_axi_wvalid       <= awvalid_in;
388			 m_axi_wdata[63:0]  <= wdata_aligned[63:0];
389			 m_axi_wstrb[7:0]   <= wstrb_aligned[7:0];
390	              end
391	            end // if ( ~axi_wvalid | w_go )
392	
393	         if( wr_access & m_axi_wvalid & ~w_go )
394	           wvalid_b <= 1'b1;
395	         else if( w_go )
396	           wvalid_b <= 1'b0;
397		  
398	          if( awvalid_in ) 
399		    begin
400	               wdata_b[63:0] <= wdata_aligned[63:0];
401	               wstrb_b[7:0]  <= wstrb_aligned[7:0];
402	            end
403	       end // else: !if(~m_axi_aresetn)
404	   
405	   
406	   //#########################################################################
407	   //Read request channel
408	   //#########################################################################
409	   //1. read request comes in on ar channel
410	   //2. use src address to match with writes coming back
411	   //3. Assumes in order returns
412	   
413	   assign  readinfo_in[40:0] = {rd_srcaddr[31:0],//40:9
414					rd_dstaddr[2:0], //8:6
415					rd_ctrlmode[3:0],//5:2
416					rd_datamode[1:0] //1:0
417					};
418	   
419	
420	   //Rest synchronization (for safety, assume incoming reset is async)
421	   wire sync_nreset;   
422	   oh_dsync dsync(.dout	(sync_nreset),
423		       .clk	(m_axi_aclk),
424		       .nreset       (1'b1),
425		       .din	(m_axi_aresetn)
426		       );
427	   
428	   //Synchronous FIFO for read transactions  	 
429	
430	   oh_fifo_sync #(.DW(104), 
431			   .DEPTH(32)) 
432	   fifo_async (.full		(fifo_full),
433		       .prog_full	(fifo_prog_full),
434		       .dout		(packet_out[103:0]),
435		       .empty		(),
436		       // Inputs
437		       .nreset		(sync_nreset),
438		       .clk	        (m_axi_aclk),
439		       .wr_en		(fifo_wr_en),
440		       .din		({63'b0,readinfo_in[40:0]}),
441		       .rd_en		(fifo_rd_en)
442		       ); 
443	
444	   assign  rr_datamode_fifo[1:0]  = packet_out[1:0];
445	   assign  rr_ctrlmode_fifo[3:0]  = packet_out[5:2];
446	   assign  rr_alignaddr_fifo[2:0] = packet_out[8:6];
447	   assign  rr_dstaddr_fifo[31:0]  = packet_out[40:9];
448	   
449	   //###################################################################
450	   //Read address channel
451	   //###################################################################
452	   
453	   assign    m_axi_araddr[31:0]   = rd_dstaddr[31:0];
454	   assign    m_axi_arsize[2:0]    = {1'b0, rd_datamode[1:0]};
455	   assign    m_axi_arlen[7:0]     = 8'd0;  
456	   assign    m_axi_arvalid        = rd_access & ~fifo_prog_full; //BUG& ~rr_wait & ~fifo_prog_full; //remove 
457	   assign    fifo_wr_en           = m_axi_arvalid & m_axi_arready ;
458	   assign    rd_wait              = ~m_axi_arready | fifo_prog_full;//BUG| rr_wait
459	   assign    fifo_rd_en           =  m_axi_rvalid & m_axi_rready;//BUG & ~rr_wait
460					      
461	   //#################################################################
462	   //Read response channel
463	   //#################################################################
464	   assign    m_axi_rready         = ~rr_wait; //BUG!: 1'b1
465	
466	   //Pipeline axi transaction to account for FIFO read latency   
467	   always @ (posedge m_axi_aclk)
468	     if(!m_axi_aresetn) 
469	       begin
470		  rr_access_fifo  <= 1'b0;	  
471		  rr_access       <= 1'b0;	  
472	       end
473	     else	 
474	       begin
475		  rr_access_fifo   <= fifo_rd_en;
476		  rr_access        <= rr_access_fifo;	  
477	       end
478	
479	   //Alignment Mux (one cycle)
480	   always @ (posedge m_axi_aclk)    
481	     begin	  
482		m_axi_rdata_fifo[63:0] <= m_axi_rdata[63:0];      	  
483		rr_datamode[1:0]       <= rr_datamode_fifo[1:0];
484		rr_ctrlmode[3:0]       <= rr_ctrlmode_fifo[3:0];
485		rr_dstaddr[31:0]       <= rr_dstaddr_fifo[31:0];	  
486		//all data needs to be right aligned
487		//(this is due to the Epiphany right aligning all words)
488		case(rr_datamode_fifo[1:0])//datamode
489	          2'd0:  // byte read
490	            case(rr_alignaddr_fifo[2:0])
491		      3'd0:     rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[7:0]};
492		      3'd1:     rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[15:8]};
493		      3'd2:     rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[23:16]};
494		      3'd3:     rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[31:24]};
495		      3'd4:     rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[39:32]};
496		      3'd5:     rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[47:40]};
497		      3'd6:     rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[55:48]};
498		      3'd7:     rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[63:56]};
499		      default:  rr_data[31:0] <= {24'b0,m_axi_rdata_fifo[7:0]};
500	            endcase	    
501	          2'd1:  // 16b hword
502	            case(rr_alignaddr_fifo[2:1])
503		      2'd0:    rr_data[31:0] <= {16'b0,m_axi_rdata_fifo[15:0]};
504		      2'd1:    rr_data[31:0] <= {16'b0,m_axi_rdata_fifo[31:16]};
505		      2'd2:    rr_data[31:0] <= {16'b0,m_axi_rdata_fifo[47:32]};
506		      2'd3:    rr_data[31:0] <= {16'b0,m_axi_rdata_fifo[63:48]};
507		      default: rr_data[31:0] <= {16'b0,m_axi_rdata_fifo[15:0]};
508	            endcase
509	          2'd2:  // 32b word
510		    begin
511	               if(rr_alignaddr_fifo[2])
512			 rr_data[31:0] <= m_axi_rdata_fifo[63:32];
513	               else
514			 rr_data[31:0] <= m_axi_rdata_fifo[31:0];
515		    end
516	          // 64b word already defined by defaults above
517	          2'd3: 
518		    begin // 64b dword
519		       rr_data[31:0]     <= m_axi_rdata_fifo[31:0];
520		       rr_srcaddr[31:0]  <= m_axi_rdata_fifo[63:32];
521	            end
522	        endcase         
523	     end // always @ (posedge m_axi_aclk1 )
524	   
525	endmodule // emaxi
526	// Local Variables:
527	// verilog-library-directories:("." "../../emesh/hdl" "../../memory/hdl" "../../common/hdl"  )
528	// End:
529	
